import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get(path, properties):
    value = execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': load(path), 'properties': properties}))['returnValue']
    return json.loads(value)

def run():
    return {
        'experience': get('/ShooterCore/Experiences/B_ShooterGame_Elimination', ['gameFeaturesToEnable', 'defaultPawnData', 'actionSets']),
        'sharedInput': get('/ShooterCore/Experiences/LAS_ShooterGame_SharedInput', ['gameFeaturesToEnable', 'actions']),
        'standardHud': get('/ShooterCore/Experiences/LAS_ShooterGame_StandardHUD', ['gameFeaturesToEnable', 'actions']),
        'pawnData': get('/ShooterCore/Game/HeroData_ShooterGame', ['pawnClass', 'abilitySets', 'tagRelationshipMapping', 'inputConfig', 'defaultCameraMode']),
        'rifleItem': get('/ShooterCore/Weapons/Rifle/ID_Rifle', ['fragments']),
        'rifleEquipment': get('/ShooterCore/Weapons/Rifle/WID_Rifle', ['instanceType', 'abilitySetsToGrant', 'actorsToSpawn']),
        'shotgunItem': get('/ShooterCore/Weapons/Shotgun/ID_Shotgun', ['fragments']),
        'shotgunEquipment': get('/ShooterCore/Weapons/Shotgun/WID_Shotgun', ['instanceType', 'abilitySetsToGrant', 'actorsToSpawn'])
    }
